package com.soldout;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * What the player has bought from each shop, and the buy clicks the server has not answered yet.
 *
 * A buy click is reserved against the item's limit the moment it is allowed, so a burst of clicks
 * inside one game tick cannot slip past the limit before the inventory catches up.
 */
class Ledger
{
	static final int UNLIMITED = -1;

	/** Game ticks a buy click stays reserved while waiting for the items to arrive. */
	static final int PENDING_TICKS = 4;

	/** Stand-in for a buy option whose amount cannot be read. */
	static final int MAX_QUANTITY = 1_000_000;

	static class Shop
	{
		/** Item id to the amount bought so far. */
		Map<Integer, Integer> bought = new HashMap<>();
		/** Item id to the stock first seen, for shops missing from the bundled table. */
		Map<Integer, Integer> seen = new HashMap<>();
	}

	private static class Pending
	{
		final String shop;
		final int item;
		final int tick;
		int quantity;

		Pending(String shop, int item, int quantity, int tick)
		{
			this.shop = shop;
			this.item = item;
			this.quantity = quantity;
			this.tick = tick;
		}
	}

	private final Map<String, Shop> shops = new HashMap<>();
	private final List<Pending> pending = new ArrayList<>();

	int bought(String shop, int item)
	{
		Shop record = shops.get(shop);
		return record == null ? 0 : record.bought.getOrDefault(item, 0);
	}

	/**
	 * How many more of an item may be bought, counting clicks still on their way to the server.
	 */
	int remaining(String shop, int item, int cap)
	{
		if (cap == UNLIMITED)
		{
			return Integer.MAX_VALUE;
		}
		long left = (long) cap - bought(shop, item) - pendingFor(shop, item);
		return (int) Math.max(0, left);
	}

	/**
	 * Reserves a buy click. Returns false, reserving nothing, when it asks for more than is left.
	 */
	boolean reserve(String shop, int item, int quantity, int cap, int tick)
	{
		if (quantity > remaining(shop, item, cap))
		{
			return false;
		}
		pending.add(new Pending(shop, item, Math.min(quantity, MAX_QUANTITY), tick));
		return true;
	}

	/**
	 * Records items that arrived in the inventory and releases the clicks that paid for them.
	 */
	void purchased(String shop, int item, int amount)
	{
		shops.computeIfAbsent(shop, k -> new Shop()).bought.merge(item, amount, Integer::sum);

		int left = amount;
		for (Iterator<Pending> it = pending.iterator(); it.hasNext() && left > 0; )
		{
			Pending p = it.next();
			if (p.item != item || !p.shop.equals(shop))
			{
				continue;
			}
			int used = Math.min(left, p.quantity);
			p.quantity -= used;
			left -= used;
			if (p.quantity == 0)
			{
				it.remove();
			}
		}
	}

	/** The shop of the oldest unanswered buy click for an item, or null. */
	String pendingShop(int item)
	{
		for (Pending p : pending)
		{
			if (p.item == item)
			{
				return p.shop;
			}
		}
		return null;
	}

	/** Drops clicks the server never answered: the shop was out of stock or the inventory was full. */
	void expire(int tick)
	{
		pending.removeIf(p -> tick - p.tick >= PENDING_TICKS);
	}

	/**
	 * Remembers the stock first seen for an item, as the limit in a shop the bundled table lacks.
	 * Returns true when it was new.
	 */
	boolean learn(String shop, int item, int stock)
	{
		return shops.computeIfAbsent(shop, k -> new Shop()).seen.putIfAbsent(item, stock) == null;
	}

	Integer seen(String shop, int item)
	{
		Shop record = shops.get(shop);
		return record == null ? null : record.seen.get(item);
	}

	void clear()
	{
		shops.clear();
		pending.clear();
	}

	String toJson(Gson gson)
	{
		return gson.toJson(shops);
	}

	void load(Gson gson, String json)
	{
		clear();
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Map<String, Shop> saved = gson.fromJson(json, new TypeToken<Map<String, Shop>>()
			{
			}.getType());
			if (saved == null)
			{
				return;
			}
			for (Map.Entry<String, Shop> entry : saved.entrySet())
			{
				Shop from = entry.getValue();
				Shop to = new Shop();
				if (from != null && from.bought != null)
				{
					to.bought.putAll(from.bought);
				}
				if (from != null && from.seen != null)
				{
					to.seen.putAll(from.seen);
				}
				shops.put(entry.getKey(), to);
			}
		}
		catch (JsonParseException | ClassCastException e)
		{
			shops.clear();
		}
	}

	private int pendingFor(String shop, int item)
	{
		long total = 0;
		for (Pending p : pending)
		{
			if (p.item == item && p.shop.equals(shop))
			{
				total += p.quantity;
			}
		}
		return (int) Math.min(total, Integer.MAX_VALUE);
	}
}

package com.soldout;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPInputStream;

/**
 * The default stock of every shop, from the bundled wiki table (see tools/generate_shops.py).
 */
class ShopData
{
	static class Shop
	{
		final String name;
		private final Map<String, Integer> stock = new HashMap<>();
		private final Map<String, Integer> aliases = new HashMap<>();

		Shop(String name)
		{
			this.name = name;
		}

		void add(String item, int amount)
		{
			String key = item.trim().toLowerCase();
			stock.merge(key, amount, ShopData::larger);

			// The wiki names some pages "Net trap (item)" where the game says "Net trap".
			int bracket = key.lastIndexOf(" (");
			if (bracket > 0 && key.endsWith(")"))
			{
				aliases.merge(key.substring(0, bracket), amount, ShopData::larger);
			}
		}

		/**
		 * Default stock of an item: {@link Ledger#UNLIMITED}, a number, or null when the shop does not stock it.
		 */
		Integer stock(String itemName)
		{
			String key = itemName.trim().toLowerCase();
			Integer amount = stock.get(key);
			return amount != null ? amount : aliases.get(key);
		}

		int size()
		{
			return stock.size();
		}
	}

	/** Shops with fewer items than this are too easy to mistake for another. */
	private static final int MIN_STOCK_MATCH = 3;

	private final Map<String, List<Shop>> byName = new HashMap<>();

	/** Adds one item to a shop, creating the shop the first time it is named. */
	void add(String shopName, String item, int amount)
	{
		List<Shop> shops = byName.computeIfAbsent(normalize(shopName), k -> new ArrayList<>());
		for (Shop shop : shops)
		{
			if (shop.name.equals(shopName))
			{
				shop.add(item, amount);
				return;
			}
		}
		Shop shop = new Shop(shopName);
		shop.add(item, amount);
		shops.add(shop);
	}

	static ShopData load() throws IOException
	{
		try (InputStream in = ShopData.class.getResourceAsStream("shops.txt.gz"))
		{
			if (in == null)
			{
				throw new IOException("shops.txt.gz is missing");
			}
			return read(new BufferedReader(new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8)));
		}
	}

	static ShopData read(BufferedReader reader) throws IOException
	{
		ShopData data = new ShopData();
		Shop shop = null;
		String line;
		while ((line = reader.readLine()) != null)
		{
			if (line.isEmpty())
			{
				continue;
			}
			if (line.charAt(0) != '\t')
			{
				shop = new Shop(line);
				data.byName.computeIfAbsent(normalize(line), k -> new ArrayList<>()).add(shop);
				continue;
			}
			String[] parts = line.split("\t");
			if (shop != null && parts.length == 3)
			{
				shop.add(parts[1], Integer.parseInt(parts[2]));
			}
		}
		return data;
	}

	/**
	 * Finds the shop with this in-game title. Shops that share a title are told apart by what they sell.
	 */
	Shop match(String title, Collection<String> itemNames)
	{
		List<Shop> candidates = byName.get(normalize(title));
		if (candidates == null)
		{
			return matchByStock(itemNames);
		}

		Shop best = null;
		int bestScore = -1;
		for (Shop candidate : candidates)
		{
			int score = 0;
			for (String item : itemNames)
			{
				if (candidate.stock(item) != null)
				{
					score++;
				}
			}
			if (score > bestScore)
			{
				best = candidate;
				bestScore = score;
			}
		}
		return best;
	}

	/**
	 * Finds a shop whose title is not in the table by what it sells. A shop keeps every item of
	 * its normal stock on the shelf, even at zero, so the shelf must hold all of a listed shop's
	 * items. Extra items on the shelf are fine: other players sold those. The largest listed
	 * shop that fits wins.
	 */
	private Shop matchByStock(Collection<String> itemNames)
	{
		Shop best = null;
		for (List<Shop> shops : byName.values())
		{
			for (Shop candidate : shops)
			{
				if (candidate.size() < MIN_STOCK_MATCH || candidate.size() > itemNames.size()
					|| (best != null && candidate.size() <= best.size()))
				{
					continue;
				}
				int found = 0;
				for (String item : itemNames)
				{
					if (candidate.stock.containsKey(item.trim().toLowerCase())
						|| candidate.aliases.containsKey(item.trim().toLowerCase()))
					{
						found++;
					}
				}
				if (found >= candidate.size())
				{
					best = candidate;
				}
			}
		}
		return best;
	}

	/**
	 * "Bob's Brilliant Axes." and "Crossbow Shop (Keldagrim)" become "bobsbrilliantaxes" and "crossbowshop".
	 */
	static String normalize(String name)
	{
		return name.toLowerCase().replaceAll("\\(.*?\\)", "").replaceAll("[^a-z0-9]", "");
	}

	private static int larger(int a, int b)
	{
		return a == Ledger.UNLIMITED || b == Ledger.UNLIMITED ? Ledger.UNLIMITED : Math.max(a, b);
	}
}

package com.soldout;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SoldOutConfig.GROUP)
public interface SoldOutConfig extends Config
{
	String GROUP = "soldout";

	@ConfigItem(
		keyName = "showRemaining",
		name = "Show amount left",
		description = "Draw how many more of each item you may buy on the shop's stock",
		position = 1
	)
	default boolean showRemaining()
	{
		return true;
	}

	@ConfigItem(
		keyName = "dimSoldOut",
		name = "Dim sold out items",
		description = "Darken items you can no longer buy",
		position = 2
	)
	default boolean dimSoldOut()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideBuyOptions",
		name = "Hide buy options over the limit",
		description = "Remove Buy options that ask for more than you have left from the right-click menu."
			+ "<br>They are blocked either way",
		position = 3
	)
	default boolean hideBuyOptions()
	{
		return true;
	}

	@ConfigItem(
		keyName = "allowUnlisted",
		name = "Allow items sold by players",
		description = "Let you buy items a shop does not normally stock, such as what other players sold"
			+ "<br>to a general store. Off: those items can never be bought",
		position = 4
	)
	default boolean allowUnlisted()
	{
		return false;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Say why a purchase was blocked",
		position = 5
	)
	default boolean chatMessages()
	{
		return true;
	}
}

package com.soldout;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws, on each item in the open shop, how many more the player may buy.
 */
class SoldOutOverlay extends Overlay
{
	private static final Color DIM = new Color(0, 0, 0, 150);
	private static final Color LEFT = new Color(0, 220, 80);
	private static final Color NONE = new Color(255, 60, 60);

	private final Client client;
	private final SoldOutPlugin plugin;
	private final SoldOutConfig config;

	@Inject
	SoldOutOverlay(Client client, SoldOutPlugin plugin, SoldOutConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		drawAfterInterface(InterfaceID.SHOPMAIN);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showRemaining() && !config.dimSoldOut())
		{
			return null;
		}

		Widget items = client.getWidget(InterfaceID.Shopmain.ITEMS);
		if (items == null || items.isHidden())
		{
			return null;
		}
		Widget[] children = items.getDynamicChildren();
		Rectangle view = items.getBounds();
		if (children == null || view == null)
		{
			return null;
		}

		Shape oldClip = graphics.getClip();
		graphics.clip(view);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = graphics.getFontMetrics();

		for (Widget child : children)
		{
			if (child == null || child.getItemId() <= 0 || child.isSelfHidden())
			{
				continue;
			}
			int left = plugin.remainingToShow(child.getItemId());
			Rectangle bounds = child.getBounds();
			if (left < 0 || bounds == null || !view.intersects(bounds))
			{
				continue;
			}

			if (left == 0 && config.dimSoldOut())
			{
				graphics.setColor(DIM);
				graphics.fill(bounds);
			}
			if (config.showRemaining())
			{
				String text = Integer.toString(left);
				int x = bounds.x + bounds.width - metrics.stringWidth(text);
				int y = bounds.y + bounds.height;
				graphics.setColor(Color.BLACK);
				graphics.drawString(text, x + 1, y + 1);
				graphics.setColor(left == 0 ? NONE : LEFT);
				graphics.drawString(text, x, y);
			}
		}

		graphics.setClip(oldClip);
		return null;
	}
}

package com.soldout;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import okhttp3.OkHttpClient;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
