@Slf4j
@PluginDescriptor(
	name = "Sold Out",
	description = "Shops only ever sell you their normal stock once: buy an item up to that amount, then never again",
	tags = {"shop", "store", "stock", "limit", "restriction", "challenge", "buy"}
)
public class SoldOutPlugin extends Plugin
{
	private static final String LEDGER_KEY = "ledger";
	private static final int INVENTORY_SIZE = 28;
	private static final int RESTOCK_MARGIN = 1;
	private static final int SELL_SETTLE_TICKS = 2;
	private static final Pattern BUY_AMOUNT = Pattern.compile("buy[ -]?(\\d{1,6})");

	/** The shop interface that is open right now. */
	private static class OpenShop
	{
		String key;
		String title;
		ShopData.Shop data;
		/** Not in the bundled table, and the wiki has not answered yet: nothing may be bought. */
		boolean checking;
		final Map<Integer, Integer> stock = new HashMap<>();
		final Map<Integer, Integer> caps = new HashMap<>();
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SoldOutOverlay overlay;

	@Inject
	private SoldOutConfig config;

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private ScheduledExecutorService executor;

	private final Ledger ledger = new Ledger();
	private final Set<String> warnedShops = new HashSet<>();
	private ShopData shopData;
	/** The wiki's table as fetched this session, or null. */
	private ShopData liveData;
	private boolean liveRequested;
	private boolean liveFailed;
	private OpenShop shop;
	private Map<Integer, Integer> inventory;
	private int lastSellTick = -100;

	@Provides
	SoldOutConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SoldOutConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		shopData = ShopData.load();
		overlayManager.add(overlay);
		clientThread.invokeLater(() ->
		{
			loadLedger();
			inventory = null;
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		shop = null;
		inventory = null;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadLedger();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// The inventory is sent afresh after a login: those items were not bought.
			inventory = null;
			shop = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		ledger.expire(client.getTickCount());
		refreshShop();
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.hideBuyOptions())
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		List<MenuEntry> kept = new ArrayList<>(entries.length);
		for (MenuEntry entry : entries)
		{
			int quantity = buyQuantity(entry);
			if (quantity > 0)
			{
				int item = itemOf(entry);
				if (deliverable(item, quantity) > remaining(item))
				{
					continue;
				}
			}
			kept.add(entry);
		}
		if (kept.size() != entries.length)
		{
			client.getMenu().setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
	}

	/**
	 * The guard. Every way of buying, a left click or any right-click option, lands here before
	 * it is sent, and a click that asks for more than is left is dropped.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.isConsumed())
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		if (isSell(entry))
		{
			lastSellTick = client.getTickCount();
			return;
		}
		int quantity = buyQuantity(entry);
		if (quantity <= 0)
		{
			return;
		}

		refreshShop();
		int item = itemOf(entry);
		if (shop == null || item <= 0)
		{
			// The shop could not be read, so nothing proves this purchase is within the limit.
			event.consume();
			return;
		}

		if (shop.checking)
		{
			event.consume();
			if (config.chatMessages())
			{
				say("Sold Out: looking up " + shop.title + " on the wiki. Try again in a moment.");
			}
			return;
		}

		int cap = cap(item);
		// Buy 5 with 3 left is fine when the shop or the inventory can only hand over 3.
		quantity = deliverable(item, quantity);
		if (ledger.reserve(shop.key, item, quantity, cap, client.getTickCount()))
		{
			return;
		}

		event.consume();
		if (config.chatMessages())
		{
			int left = ledger.remaining(shop.key, item, cap);
			String name = itemManager.getItemComposition(item).getName();
			say(left == 0
				? "Sold out: " + shop.title + " will never sell you another " + name + "."
				: "Sold out: you can only buy " + left + " more " + name + " from " + shop.title + ".");
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		Map<Integer, Integer> now = count(event.getItemContainer());
		Map<Integer, Integer> before = inventory;
		inventory = now;
		if (before == null)
		{
			return;
		}

		refreshShop();
		boolean changed = false;
		for (Map.Entry<Integer, Integer> entry : now.entrySet())
		{
			int item = entry.getKey();
			int gained = entry.getValue() - before.getOrDefault(item, 0);
			if (gained <= 0)
			{
				continue;
			}

			// A buy click still waiting names its shop even if the interface was closed since.
			String key = ledger.pendingShop(item);
			if (key == null && shop != null && shop.stock.containsKey(item))
			{
				key = shop.key;
			}
			if (key != null)
			{
				ledger.purchased(key, item, gained);
				changed = true;
			}
		}
		if (changed)
		{
			saveLedger();
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!"soldout".equalsIgnoreCase(event.getCommand()))
		{
			return;
		}
		String[] args = event.getArguments();
		if (args.length == 1 && "reset".equalsIgnoreCase(args[0]))
		{
			ledger.clear();
			saveLedger();
			if (shop != null)
			{
				shop.caps.clear();
			}
			say("Sold Out: every shop's stock is yours to buy again.");
		}
		else
		{
			say("Sold Out: type ::soldout reset to forget everything you have bought.");
		}
	}

	/** How many more of an item the open shop will sell, or -1 when there is no limit to show. */
	int remainingToShow(int item)
	{
		if (shop == null)
		{
			return -1;
		}
		int cap = cap(item);
		return cap == Ledger.UNLIMITED ? -1 : ledger.remaining(shop.key, item, cap);
	}

	/**
	 * The amount a menu entry would buy from the shop, or 0 when it is not a shop buy option.
	 */
	private static int buyQuantity(MenuEntry entry)
	{
		if (entry.getParam1() != InterfaceID.Shopmain.ITEMS || entry.getOption() == null)
		{
			return 0;
		}
		return buyQuantity(entry.getOption());
	}

	private static boolean isSell(MenuEntry entry)
	{
		return entry.getParam1() == InterfaceID.Shopside.ITEMS && entry.getOption() != null
			&& Text.removeTags(entry.getOption()).trim().toLowerCase().startsWith("sell");
	}

	/**
	 * The most a buy option can really hand over: no more than the shop holds or the inventory fits.
	 */
	private int deliverable(int item, int quantity)
	{
		refreshShop();
		if (shop == null || item <= 0)
		{
			return quantity;
		}

		int most = quantity;
		Integer stock = shop.stock.get(item);
		if (stock != null && stock >= 0)
		{
			// One spare, in case the shop restocks between the click and the server's answer.
			most = Math.min(most, stock + RESTOCK_MARGIN);
		}

		// A sale just made may free slots the client has not heard about yet.
		if (client.getTickCount() - lastSellTick > SELL_SETTLE_TICKS)
		{
			most = Math.min(most, roomFor(item));
		}
		return most;
	}

	/** How many of an item the inventory can take. */
	private int roomFor(int item)
	{
		ItemContainer container = client.getItemContainer(InventoryID.INV);
		int used = 0;
		boolean held = false;
		if (container != null)
		{
			for (Item slot : container.getItems())
			{
				if (slot.getId() > 0)
				{
					used++;
					held |= slot.getId() == item;
				}
			}
		}
		int free = Math.max(0, INVENTORY_SIZE - used);
		if (itemManager.getItemComposition(item).isStackable())
		{
			return held || free > 0 ? Ledger.MAX_QUANTITY : 0;
		}
		return free;
	}

	static int buyQuantity(String option)
	{
		String text = Text.removeTags(option).trim().toLowerCase();
		if (!text.startsWith("buy"))
		{
			return 0;
		}
		Matcher matcher = BUY_AMOUNT.matcher(text);
		// An amount that cannot be read is treated as "everything", which only unlimited items allow.
		return matcher.matches() ? Math.max(1, Integer.parseInt(matcher.group(1))) : Ledger.MAX_QUANTITY;
	}

	private static int itemOf(MenuEntry entry)
	{
		Widget widget = entry.getWidget();
		int item = widget != null ? widget.getItemId() : -1;
		return item > 0 ? item : entry.getItemId();
	}

	private int remaining(int item)
	{
		refreshShop();
		if (shop == null || item <= 0)
		{
			return 0;
		}
		return ledger.remaining(shop.key, item, cap(item));
	}

	/** The most of an item the open shop will ever sell this player. */
	private int cap(int item)
	{
		if (shop.checking)
		{
			return 0;
		}
		Integer known = shop.caps.get(item);
		if (known != null)
		{
			return known;
		}

		int cap;
		if (shop.data != null)
		{
			Integer listed = shop.data.stock(itemManager.getItemComposition(item).getName());
			if (listed != null)
			{
				cap = listed;
			}
			else
			{
				cap = config.allowUnlisted() ? Ledger.UNLIMITED : 0;
			}
		}
		else
		{
			Integer seen = ledger.seen(shop.key, item);
			cap = seen != null ? seen : shop.stock.getOrDefault(item, 0);
		}
		shop.caps.put(item, cap);
		return cap;
	}

	/**
	 * Reads the open shop: its title, its current stock, and its row in the bundled table.
	 */
	private void refreshShop()
	{
		Widget items = client.getWidget(InterfaceID.Shopmain.ITEMS);
		if (items == null || items.isHidden())
		{
			shop = null;
			return;
		}

		String title = shopTitle();
		String key = ShopData.normalize(title);
		if (shop == null || !shop.key.equals(key))
		{
			shop = new OpenShop();
			shop.key = key;
			shop.title = title;
		}

		shop.stock.clear();
		Widget[] children = items.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child != null && child.getItemId() > 0 && !child.isSelfHidden())
				{
					shop.stock.merge(child.getItemId(), child.getItemQuantity(), Integer::sum);
				}
			}
		}
		if (shop.stock.isEmpty())
		{
			return;
		}

		if (shop.data == null)
		{
			List<String> names = new ArrayList<>();
			for (int item : shop.stock.keySet())
			{
				names.add(itemManager.getItemComposition(item).getName());
			}
			shop.data = shopData.match(title, names);
			if (shop.data == null && liveData != null)
			{
				shop.data = liveData.match(title, names);
			}
			shop.caps.clear();
		}

		shop.checking = shop.data == null && liveData == null && !liveFailed;
		if (shop.checking)
		{
			requestLiveData();
		}
		else if (shop.data == null)
		{
			learnStock();
		}
	}

	/**
	 * Asks the wiki for its current table, once a session, the first time a shop is not recognised.
	 */
	private void requestLiveData()
	{
		if (liveRequested)
		{
			return;
		}
		liveRequested = true;
		executor.execute(() ->
		{
			try
			{
				ShopData fetched = WikiShops.fetch(okHttpClient, gson);
				clientThread.invoke(() -> liveData = fetched);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not read shop stock from the wiki", e);
				clientThread.invoke(() -> liveFailed = true);
			}
		});
	}

	/** A shop missing from the table: the stock it has when first seen becomes its limit. */
	private void learnStock()
	{
		boolean learned = false;
		for (Map.Entry<Integer, Integer> entry : shop.stock.entrySet())
		{
			learned |= ledger.learn(shop.key, entry.getKey(), entry.getValue());
		}
		if (learned)
		{
			saveLedger();
		}
		if (warnedShops.add(shop.key) && config.chatMessages())
		{
			say("Sold Out: " + shop.title + (liveFailed ? " is not in the stock list and the wiki could not be reached"
				: " is not on the wiki") + ", so the stock it had when you first saw it is the most it will sell you.");
		}
	}

	private String shopTitle()
	{
		Widget frame = client.getWidget(InterfaceID.Shopmain.FRAME);
		if (frame != null)
		{
			Widget[] children = frame.getDynamicChildren();
			if (children != null)
			{
				for (Widget child : children)
				{
					String text = child == null ? null : child.getText();
					if (text != null && !Text.removeTags(text).trim().isEmpty())
					{
						return Text.removeTags(text).trim();
					}
				}
			}
		}
		return "This shop";
	}

	private static Map<Integer, Integer> count(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && item.getQuantity() > 0)
				{
					counts.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return counts;
	}

	private void loadLedger()
	{
		ledger.load(gson, configManager.getRSProfileConfiguration(SoldOutConfig.GROUP, LEDGER_KEY));
		shop = null;
	}

	private void saveLedger()
	{
		if (configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(SoldOutConfig.GROUP, LEDGER_KEY, ledger.toJson(gson));
		}
	}

	private void say(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}
}

package com.soldout;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Reads the current shop stock table from the OSRS Wiki, for shops newer than the bundled copy.
 */
class WikiShops
{
	private static final String API = "https://oldschool.runescape.wiki/api.php";
	private static final int PAGE = 5000;
	private static final int MAX_ROWS = 50_000;

	static ShopData fetch(OkHttpClient http, Gson gson) throws IOException
	{
		ShopData data = new ShopData();
		for (int offset = 0; offset < MAX_ROWS; offset += PAGE)
		{
			String query = "bucket('storeline').select('sold_by','sold_item','store_stock')"
				+ ".limit(" + PAGE + ").offset(" + offset + ").run()";
			HttpUrl url = HttpUrl.get(API).newBuilder()
				.addQueryParameter("action", "bucket")
				.addQueryParameter("format", "json")
				.addQueryParameter("query", query)
				.build();

			try (Response response = http.newCall(new Request.Builder().url(url).build()).execute())
			{
				if (!response.isSuccessful() || response.body() == null)
				{
					throw new IOException("wiki answered " + response.code());
				}
				JsonObject root = gson.fromJson(response.body().charStream(), JsonObject.class);
				JsonArray rows = root == null ? null : root.getAsJsonArray("bucket");
				if (rows == null)
				{
					throw new IOException("wiki answer has no rows");
				}
				for (JsonElement element : rows)
				{
					JsonObject row = element.getAsJsonObject();
					Integer stock = parseStock(text(row, "store_stock"));
					String shop = text(row, "sold_by");
					String item = text(row, "sold_item");
					if (stock != null && !shop.isEmpty() && !item.isEmpty())
					{
						data.add(shop, item, stock);
					}
				}
				if (rows.size() < PAGE)
				{
					break;
				}
			}
			catch (JsonParseException | IllegalStateException | ClassCastException e)
			{
				throw new IOException("wiki answer could not be read", e);
			}
		}
		return data;
	}

	/** A number, {@link Ledger#UNLIMITED} for the wiki's infinity sign, or null for anything else. */
	static Integer parseStock(String text)
	{
		String value = text.replace(",", "").trim();
		if (value.equals("∞"))
		{
			return Ledger.UNLIMITED;
		}
		if (value.isEmpty() || value.length() > 9 || !value.chars().allMatch(c -> c >= '0' && c <= '9'))
		{
			return null;
		}
		return Integer.parseInt(value);
	}

	private static String text(JsonObject row, String field)
	{
		JsonElement value = row.get(field);
		return value == null || !value.isJsonPrimitive() ? "" : value.getAsString().trim();
	}
}

package com.soldout;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LedgerTest
{
	private static final String SHOP = "varrockgeneralstore";
	private static final int BUCKET = 1925;

	private final Ledger ledger = new Ledger();

	@Test
	public void buyFiveIsRefusedWhenOneIsLeft()
	{
		ledger.purchased(SHOP, BUCKET, 2);

		assertEquals(1, ledger.remaining(SHOP, BUCKET, 3));
		assertFalse(ledger.reserve(SHOP, BUCKET, 5, 3, 10));
		assertTrue(ledger.reserve(SHOP, BUCKET, 1, 3, 10));
	}

	@Test
	public void clicksInTheSameTickCannotPassTheLimit()
	{
		assertTrue(ledger.reserve(SHOP, BUCKET, 1, 3, 10));
		assertTrue(ledger.reserve(SHOP, BUCKET, 1, 3, 10));
		assertTrue(ledger.reserve(SHOP, BUCKET, 1, 3, 10));
		assertFalse(ledger.reserve(SHOP, BUCKET, 1, 3, 10));
		assertEquals(0, ledger.remaining(SHOP, BUCKET, 3));
	}

	@Test
	public void refusedClickReservesNothing()
	{
		assertFalse(ledger.reserve(SHOP, BUCKET, 5, 3, 10));
		assertEquals(3, ledger.remaining(SHOP, BUCKET, 3));
	}

	@Test
	public void arrivingItemsReleaseTheirClick()
	{
		ledger.reserve(SHOP, BUCKET, 5, 10, 10);
		ledger.purchased(SHOP, BUCKET, 5);

		assertEquals(5, ledger.bought(SHOP, BUCKET));
		assertEquals(5, ledger.remaining(SHOP, BUCKET, 10));
		assertNull(ledger.pendingShop(BUCKET));
	}

	@Test
	public void shortDeliveryCountsOnlyWhatArrived()
	{
		// Buy 5 with two in stock: two arrive, the other three are never charged.
		ledger.reserve(SHOP, BUCKET, 5, 10, 10);
		ledger.purchased(SHOP, BUCKET, 2);
		assertEquals(5, ledger.remaining(SHOP, BUCKET, 10));

		ledger.expire(10 + Ledger.PENDING_TICKS);
		assertEquals(8, ledger.remaining(SHOP, BUCKET, 10));
	}

	@Test
	public void unansweredClickExpires()
	{
		ledger.reserve(SHOP, BUCKET, 3, 3, 10);
		ledger.expire(10 + Ledger.PENDING_TICKS - 1);
		assertEquals(0, ledger.remaining(SHOP, BUCKET, 3));

		ledger.expire(10 + Ledger.PENDING_TICKS);
		assertEquals(3, ledger.remaining(SHOP, BUCKET, 3));
	}

	@Test
	public void unlimitedStockIsNeverRefused()
	{
		assertTrue(ledger.reserve(SHOP, BUCKET, Ledger.MAX_QUANTITY, Ledger.UNLIMITED, 10));
		assertTrue(ledger.reserve(SHOP, BUCKET, Ledger.MAX_QUANTITY, Ledger.UNLIMITED, 10));
		assertEquals(Integer.MAX_VALUE, ledger.remaining(SHOP, BUCKET, Ledger.UNLIMITED));
	}

	@Test
	public void shopsAndItemsAreSeparate()
	{
		ledger.purchased(SHOP, BUCKET, 3);

		assertEquals(3, ledger.remaining("lumbridgegeneralstore", BUCKET, 3));
		assertEquals(2, ledger.remaining(SHOP, 1931, 2));
	}

	@Test
	public void buyingMoreThanTheLimitNeverGoesNegative()
	{
		ledger.purchased(SHOP, BUCKET, 9);
		assertEquals(0, ledger.remaining(SHOP, BUCKET, 3));
	}

	@Test
	public void firstSeenStockSticks()
	{
		assertTrue(ledger.learn(SHOP, BUCKET, 4));
		assertFalse(ledger.learn(SHOP, BUCKET, 30));
		assertEquals(Integer.valueOf(4), ledger.seen(SHOP, BUCKET));
	}

	@Test
	public void survivesSaveAndLoad()
	{
		Gson gson = new Gson();
		ledger.purchased(SHOP, BUCKET, 2);
		ledger.learn("odd shop", 4151, 1);

		Ledger loaded = new Ledger();
		loaded.load(gson, ledger.toJson(gson));

		assertEquals(2, loaded.bought(SHOP, BUCKET));
		assertEquals(Integer.valueOf(1), loaded.seen("odd shop", 4151));
	}

	@Test
	public void badSaveLoadsEmpty()
	{
		ledger.load(new Gson(), "not json {");
		assertEquals(0, ledger.bought(SHOP, BUCKET));

		ledger.load(new Gson(), null);
		assertEquals(0, ledger.bought(SHOP, BUCKET));
	}
}

package com.soldout;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;
import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ShopDataTest
{
	private static ShopData sample() throws IOException
	{
		String text = "Bob's Brilliant Axes.\n"
			+ "\tBronze axe\t10\n"
			+ "\tSteel axe\t3\n"
			+ "Crossbow Shop (Keldagrim)\n"
			+ "\tBronze crossbow\t2\n"
			+ "Crossbow Shop (Dwarven Mine)\n"
			+ "\tBronze limbs\t10\n"
			+ "Hunter shop\n"
			+ "\tNet trap (item)\t25\n"
			+ "\tWaterskin(4)\t-1\n";
		return ShopData.read(new BufferedReader(new StringReader(text)));
	}

	@Test
	public void titleMatchesWhateverThePunctuation() throws IOException
	{
		ShopData.Shop shop = sample().match("Bob's Brilliant Axes", Collections.emptyList());

		assertNotNull(shop);
		assertEquals(Integer.valueOf(3), shop.stock("Steel axe"));
		assertEquals(Integer.valueOf(10), shop.stock("bronze AXE"));
	}

	@Test
	public void unstockedItemHasNoStock() throws IOException
	{
		assertNull(sample().match("Bob's Brilliant Axes.", Collections.emptyList()).stock("Rune axe"));
	}

	@Test
	public void unknownShopDoesNotMatch() throws IOException
	{
		assertNull(sample().match("Zaff's Superior Staffs!", Collections.emptyList()));
	}

	@Test
	public void renamedShopIsFoundByItsStock() throws IOException
	{
		String text = "Helmet Shop\n\tBronze med helm\t5\n\tIron med helm\t3\n\tSteel med helm\t2\n"
			+ "Tiny Shop\n\tBronze med helm\t9\n";
		ShopData data = ShopData.read(new BufferedReader(new StringReader(text)));

		// A player sold the rune helm; the shelf still holds the shop's whole normal stock.
		ShopData.Shop shop = data.match("Peksa's Helmets",
			Arrays.asList("Bronze med helm", "Iron med helm", "Steel med helm", "Rune med helm"));
		assertEquals("Helmet Shop", shop.name);

		// Missing one of the listed items: not that shop.
		assertNull(data.match("Peksa's Helmets", Arrays.asList("Bronze med helm", "Iron med helm", "Rune med helm")));
	}

	@Test
	public void sameTitleIsToldApartByStock() throws IOException
	{
		ShopData.Shop shop = sample().match("Crossbow Shop", Arrays.asList("Bronze limbs"));
		assertEquals("Crossbow Shop (Dwarven Mine)", shop.name);
	}

	@Test
	public void wikiPageSuffixIsIgnored() throws IOException
	{
		ShopData.Shop shop = sample().match("Hunter shop", Collections.emptyList());

		assertEquals(Integer.valueOf(25), shop.stock("Net trap"));
		assertEquals(Integer.valueOf(Ledger.UNLIMITED), shop.stock("Waterskin(4)"));
	}

	@Test
	public void bundledTableLoads() throws IOException
	{
		ShopData.Shop shop = ShopData.load().match("Varrock General Store", Collections.emptyList());

		assertNotNull(shop);
		assertEquals(Integer.valueOf(3), shop.stock("Bucket"));
	}

	@Test
	public void wikiStockValues()
	{
		assertEquals(Integer.valueOf(1000), WikiShops.parseStock("1,000"));
		assertEquals(Integer.valueOf(Ledger.UNLIMITED), WikiShops.parseStock("∞"));
		assertNull(WikiShops.parseStock("N/A"));
		assertNull(WikiShops.parseStock(""));
	}

	@Test
	public void rowsAddedOneByOneBuildShops()
	{
		ShopData data = new ShopData();
		data.add("New Shop", "Rope", 5);
		data.add("New Shop", "Rope", 8);
		data.add("New Shop", "Spade", 2);

		ShopData.Shop shop = data.match("New Shop.", Collections.emptyList());
		assertEquals(2, shop.size());
		assertEquals(Integer.valueOf(8), shop.stock("Rope"));
	}

	@Test
	public void buyOptionAmounts()
	{
		assertEquals(1, SoldOutPlugin.buyQuantity("Buy 1"));
		assertEquals(50, SoldOutPlugin.buyQuantity("<col=ff9040>Buy 50</col>"));
		assertEquals(5, SoldOutPlugin.buyQuantity("Buy-5"));
		assertEquals(Ledger.MAX_QUANTITY, SoldOutPlugin.buyQuantity("Buy-X"));
		assertEquals(0, SoldOutPlugin.buyQuantity("Value"));
		assertEquals(0, SoldOutPlugin.buyQuantity("Sell 5"));
	}
}

